suppressMessages(library(dplyr))
u<-readRDS("data/european_elections/final/european_muni_unharm.rds")
print(as.data.frame(u%>%group_by(election_year)%>%summarise(bad2=sum(number_voters>eligible_voters,na.rm=T),bad3=sum(abs(valid_votes+invalid_votes-number_voters)>1,na.rm=T),bad3sum=sum(valid_votes+invalid_votes-number_voters))))
print(u%>%filter(abs(valid_votes+invalid_votes-number_voters)>1)%>%mutate(d=valid_votes+invalid_votes-number_voters)%>%arrange(desc(abs(d)))%>%select(ags,state_name,election_year,eligible_voters,number_voters,valid_votes,invalid_votes,d)%>%head(15))
print(u%>%filter(number_voters>eligible_voters)%>%select(ags,election_year,eligible_voters,number_voters,turnout,flag_turnout_above_1)%>%head(12))
print(u%>%filter(turnout<0.3)%>%select(ags,election_year,eligible_voters,number_voters,turnout)%>%head(12))
print(table(u$election_year[u$turnout==1]))
print(u%>%filter(flag_turnout_above_1==1, number_voters/eligible_voters<=1)%>%nrow())
print(u%>%filter(abs(turnout-number_voters/eligible_voters)>0.001)%>%select(ags,election_year,eligible_voters,number_voters,turnout,flag_turnout_above_1)%>%head(10))
